use super::compose::OutgoingMessage;
use super::config::Settings;
use super::model::MessageId;
use super::store::Store;

/// Effects that cannot be performed by the store alone and are executed by the caller.
#[derive(Clone, Debug)]
pub enum SideEffect {
    Notify { title: String, body: String },
    PlaySound(String),
    /// Send a message (reply / forward / redirect generated by a rule).
    Send(Box<OutgoingMessage>),
    /// Run a shell command; the message source path is passed as `$1`.
    RunCommand { command: String, message: MessageId },
    /// The message list / sidebar must be refreshed.
    Changed,
}

/// Apply all enabled rules (or only `only_rule`) to the given messages.
pub fn apply_rules(_store: &Store, _settings: &Settings, _ids: &[MessageId], _only_rule: Option<&str>) -> Vec<SideEffect> {
    Vec::new()
}
